properties":{"careContexts":{"description":"List of care contexts linked at the HIP end for the identified patient.","items":{"nullable":true,"properties":{"careContextReference":{"description":"An identifier of patient's care context created in HIP. A care context is a group of patient's health data (Not the actual health data)","example":"Episode1","type":"string"},"patientReference":{"description":"A patient identifier with which patient is registered in the facility/hospital","example":"batman@tmh","type":"string"}},"required":["patientReference","careContextReference"],"type":"object"},"type":"array"},"consentId":{"description":"Allows alpha numeric character and special characters like "^[0-9a-fA-F]{8}\\b-[0-9a-fA-F]{4}\\b-[0-9a-fA-F]{4}\\b-[0-9a-fA-F]{4}\\b-[0-9a-fA-F]{12}$";","example":"e5ec415f-c098-40f6-a0db-faa162fc5295","nullable":true,"type":"string"},"consentManager":{"properties":{"id":{"example":"abdm","type":"string"}},"type":"object"},"createdAt":{"example":"2021-09-28T12:30:08.573Z","format":"date-time","type":"string"},"hiTypes":{"description":"Types of health information document.","items":{"enum":["DiagnosticReport","DischargeSummary","HealthDocumentRecord","ImmunizationRecord","OPConsultation","Prescription","WellnessRecord","Invoice"],"example":"Prescription","type":"string"},"type":"array"},"hip":{"description":"Identifier and name of the health information provider.","nullable":true,"properties":{"id":{"description":"The service ID of the health information provider. Allows alpha numeric character and special characters like [A-Z a-z 0-9]+[A-Z a-z 0-9 //_//-]*[A-Z a-z 0-9]$","example":"cowin_hip_01","type":"string"},"name":{"description":"The name of the health information provider. Allows alpha numeric and special characters like _\-@,():/","example":"Cowin","nullable":true,"type":"string"},"type":{"description":"The type of the health information provider. Allows alpha numeric and special characters like _\-@,. ":/","example":"HIP","nullable":true,"type":"string"}},"required":["id","name"],"type":"object"},"hiu":{"properties":{"id":{"description":"The service ID of the health information user.  Allows alpha numeric character and special characters like [A-Z a-z 0-9]+[A-Z a-z 0-9 //_//-]*[A-Z a-z 0-9]$","example":"cowin_hiu_01","type":"string"},"name":{"description":"The name of the health information user. Allows alpha numeric and special characters like _\-@,():/","example":"Cowin","nullable":true,"type":"string"},"type":{"description":"The type of the health information user. Allows alpha numeric and special characters like _\-@,. ":/","example":"HIU","nullable":true,"type":"string"}},"required":["id","name"],"type":"object"},"lastUpdated":{"example":"2021-09-28T12:30:08.573Z","format":"date-time","type":"string"},"patient":{"properties":{"id":{"description":"The abha address of the patient","example":"<ABHA_ADDRESS>","type":"string"}},"required":["id"],"type":"object"},"permission":{"properties":{"accessMode":{"enum":["VIEW","STORE","STREAM","QUERY"],"example":"VIEW","type":"string"},"dataEraseAt":{"description":"The date at which the consent expire. Should be UTC date time in ISO format","example":"2021-09-28T12:30:08.573Z","format":"date-time","type":"string"},"dateRange":{"properties":{"from":{"description":"Should be UTC date time in ISO format","example":"2021-09-28T12:30:08.573Z","format":"date-time","type":"string"},"to":{"description":"Should be UTC date time in ISO format","example":"2021-09-28T12:30:08.573Z","format":"date-time","type":"string"}},"required":["from","to"],"type":"object"},"frequency":{"properties":{"repeats":{"description":"Should be be a integer","example":0,"format":"int32","nullable":true,"type":"number"},"unit":{"enum":["HOUR","DAY","WEEK","MONTH","YEAR"],"type":"string"},"value":{"description":"The frequency unit value. Should be be a integer","example":1,"format":"int32","type":"number"}},"required":["unit","value","repeats"],"type":"object"}},"required":["accessMode","dateRange","dataEraseAt","frequency"],"type":"object"},"purpose":{"properties":{"code":{"enum":["CAREMGT","BTG","PUBHLTH","HPAYMT","DSRCH","PATRQT"],"type":"string"},"refUri":{"description":"The reference URL. Should be a valid URL","example":"www.abc.com","type":"string"},"text":{"enum":["Care Management","Break the Glass","Public Health","Healthcare Payment","Disease Specific Healthcare Research","Self Requested"],"type":"string"}},"required":["text","code","refUri"],"type":"object"},"requester":{"nullable":true,"properties":{"identifier":{"properties":{"system":{"description":"Allows alpha numeric character and special characters like _\-@,. ":/","example":"https://www.sample.com","type":"string"},"type":{"description":"The identification value. Allows alpha numeric character and special characters like _\-@,. ":/","example":"MH1001","type":"string"},"value":{"description":"The type of the identification. Allows alpha numeric character and special characters like _\-@,. ":/","example":"REG1","type":"string"}},"required":["value","type","system"],"type":"object"},"name":{"description":"The name of the requester","example":"<ABHA_ADDRESS>","type":"string"}},"required":["name","identifier"],"type":"object"},"schemaVersion":{"example":"v3","type":"string"}},"required":["purpose","patient","hiu","requester","hiTypes","permission"],"type":"object"},"signature":{"example":"Signature of CM as defined in W3C standards; Base64 encoded","type":"string"},"status":{"enum":["GRANTED","DENIED","EXPIRED","REVOKED"],"example":"GRANTED","type":"string"}},"required":["status","consentDetail","signature"],"type":"object"}}},"description":"Ok"},"400":{"content":{"application/json":{"schema":{"properties":{"error":{"description":"The error code and message, if any occurred.","properties":{"code":{"description":"ABDM-1080 - Invalid Consent artefact id. May be returned either bare or with a trailing ": " separator; match on the code itself and tolerate the separator.","example":"AB