ring"},"message":{"example":"Unclassified Authentication Failure","type":"string"}},"type":"object"}}},"description":"Internal Server Error"},"503":{"content":{"application/json":{"schema":{"properties":{"code":{"description":"ABDM-1024 - Dependent service unavailable. May be returned either bare (`ABDM-1024`) or with a trailing ": " separator (`ABDM-1024: `); match on the code itself and tolerate the separator.","example":"ABDM-1024","pattern":"^(ABDM-\d{4}|\d{3,6})(: )?$","type":"string"},"message":{"example":"Dependent service unavailable","type":"string"}},"required":["code","message"],"type":"object"}}},"description":"Service Unavailable"}},"security":[{"bearerAuth":[]}],"summary":"This is ABDM HIE-CM API called to fetch the consent artefact details associated with the artefact-id.","tags":["consent-management-data-flow-phr"],"x-abdm-nha-operation-id":"abdm-consent-management 6 (2)"}}
